package com.pharmapack.qms.production; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.util.*; public interface ProductionEntryRepository extends JpaRepository<ProductionEntry,Long>{ @EntityGraph(attributePaths={"productionRun","productionRun.batch","productionRun.batch.product","productionRun.line","productionRun.equipment"}) List<ProductionEntry> findByProductionRunIdOrderByEntryTimeAsc(Long id); @EntityGraph(attributePaths={"productionRun","productionRun.batch","productionRun.batch.product"}) Optional<ProductionEntry> findById(Long id);
 /** Total produced so far for a batch, across all of its production runs (lot-size control). */
 @Query("select coalesce(sum(e.quantityProduced), 0) from ProductionEntry e where e.productionRun.batch.id = :batchId") BigDecimal sumProducedByBatchId(@Param("batchId") Long batchId); }
